import{_ as t,o,c as i,a3 as n}from"./chunks/framework.DACwFHq9.js";const g=JSON.parse('{"title":"Git Synchronization & Remote Backup","description":"Sync notes securely between devices using Git remote repositories (GitHub, GitLab, self-hosted).","frontmatter":{"title":"Git Synchronization & Remote Backup","description":"Sync notes securely between devices using Git remote repositories (GitHub, GitLab, self-hosted).","keywords":"Git, sync, remote, push, pull, version control, backup","category":"Sync"},"headers":[],"relativePath":"sync/index.md","filePath":"sync/index.md","lastUpdated":1791044111000}'),s={name:"sync/index.md"};function r(l,e,a,c,d,h){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="git-sync" tabindex="-1">Git Sync <a class="header-anchor" href="#git-sync" aria-label="Permalink to &quot;Git Sync&quot;">​</a></h1><p>Notely integrates directly with Git to provide robust, decentralized version control and multi-device synchronization.</p><hr><h2 id="_1-setting-up-remote-sync" tabindex="-1">1. Setting Up Remote Sync <a class="header-anchor" href="#_1-setting-up-remote-sync" aria-label="Permalink to &quot;1. Setting Up Remote Sync&quot;">​</a></h2><ol><li>Open <strong>Tools → Version Control</strong> (<code>Ctrl/Cmd + Shift + G</code>).</li><li>If the workspace is not initialized, click <strong>Initialize Git Repository</strong>.</li><li>Under the <strong>Remotes</strong> section, add your remote repository URL (e.g. <code>git@github.com:username/notes.git</code> or <code>https://...</code>).</li><li>Configure SSH keys or credential helpers as needed.</li></ol><hr><h2 id="_2-syncing-notes-pull-push" tabindex="-1">2. Syncing Notes (Pull &amp; Push) <a class="header-anchor" href="#_2-syncing-notes-pull-push" aria-label="Permalink to &quot;2. Syncing Notes (Pull &amp; Push)&quot;">​</a></h2><ul><li><strong>One-Click Sync</strong>: Use the title bar menu <strong>Tools → Version Control → Sync (Pull then Push)</strong> or the Git sidebar action.</li><li><strong>Pull</strong>: Fetches and merges updates from the configured tracking branch.</li><li><strong>Push</strong>: Publishes local commits to the remote repository.</li></ul><hr><h2 id="_3-conflict-resolution" tabindex="-1">3. Conflict Resolution <a class="header-anchor" href="#_3-conflict-resolution" aria-label="Permalink to &quot;3. Conflict Resolution&quot;">​</a></h2><ul><li>When remote changes overlap with local edits, Git creates conflict markers.</li><li>Notely&#39;s built-in <strong>Git Version Control</strong> panel highlights conflicted files with a dedicated diff viewer, allowing you to resolve and stage changes seamlessly.</li></ul>',11)])])}const p=t(s,[["render",r]]);export{g as __pageData,p as default};
